from agent_identity import agent_label
from final_identity import final_label
"""Assemble a reviewable report from completed raw evidence, without judging quality."""
from pathlib import Path
import json,statistics,shlex,re,time
R=Path(__file__).resolve().parent
def load(p):return json.loads(Path(p).read_text())
def med(rows,key):return statistics.median(x[key] for x in rows if isinstance(x.get(key),(int,float)))
def fmt(x):return 'n/a' if x is None else ('YES' if x else 'NO') if isinstance(x,bool) else f'{x:.2f}' if isinstance(x,(int,float)) else str(x)
def arg(cfg,flag,default='default'):
    a=cfg['args'];return a[a.index(flag)+1] if flag in a else default
def table(headers,rows):
    return '\n'.join(['| '+' | '.join(headers)+' |','|'+'|'.join('---' for _ in headers)+'|',*['| '+' | '.join(fmt(x) for x in row)+' |' for row in rows]])

if __name__=='__main__':
    required=['final-matrix','long','agent64','agent128','compaction','compaction-old-control','quality','needle','iq3','diagnostics']
    for phase in required:assert load(R/'raw'/f'phase-{phase}-terminal.json')['status']=='COMPLETE',phase
    summary=load(R/'summary.json');records=summary['records'];comparison=load(R/'comparison-upgrade.json');cfg=load(R/'configs/FINAL-v0132-Q4.json');iqcfg=load(R/'configs/IQ3-upgrade-control.json')
    final=[x for x in records if x['candidate']==final_label() and x['kind']=='candidate'];assert len(final)==12
    context=[]
    for target in [31400,63400,127000,259500]:
        rows=[x for x in final if abs(x['actual_prompt_tokens']-target)<=8];assert len(rows)==3
        context.append([med(rows,'actual_prompt_tokens'),med(rows,'PP_tps'),med(rows,'TG_tps'),med(rows,'TTFT_s'),med(rows,'RAM_used_GiB'),med(rows,'VRAM0_GiB'),med(rows,'VRAM1_GiB'),med(rows,'MTP_accept')])
    controlled=load(R/'comparison-pp-control.json')['rows'];quality=load(R/'raw/quality-parity-summary.json');needle=load(R/'raw/needle-summary.json');diagnostics=load(R/'raw/diagnostic-summary.json')
    topology=load(R/'raw/topology-selection.json');calibration=load(R/'raw/calibration-selection.json');mtp=load(R/'raw/mtp-selection.json');kv=load(R/'raw/kv-selection.json');selection=load(R/'raw/final-selection.json');prefill=load(R/'raw/prefill-policy-reviewed.json');placement=load(R/'raw/placement-comparison.json')
    prompt=load(R/'raw/prompt-modes-selection.json');base=load(R/'raw/baseline-summary.json');longs=load(R/'raw/long-decode-done.json')['runs'];compaction=load(R/'raw/COMPACTION-FINAL-v0132-done.json')['runs'];agents={t:load(R/'raw'/f'{agent_label(t)}-done.json')['runs'] for t in [63400,127000]}
    for name,source in [('production-Q4',cfg),('production-IQ3_S',iqcfg)]:
        copied=dict(source);copied['log']=str(R/'logs'/f'{name}.log')
        # Custom external harness fields are not interpreted by the upstream server.
        # Persist opt-ins through its official cfg.env interface, with the same normal timing flags.
        copied['env']=dict(source.get('env') or {},STRATA_SPLIT_TIMING='1',STRATA_DECODE_TIMING='1')
        copied['env'].update(source.get('environment_overrides',{}))
        (R/'configs'/f'{name}.json').write_text(json.dumps(copied,indent=2))
    qcommand='cd /srv/ai/strata-v0.1.32 && env -u STRATA_SPLIT_OWN -u STRATA_KV_ROT -u STRATA_REFILL_SERIAL -u STRATA_SPEC_COUPLED CUDA_VISIBLE_DEVICES=0,1 .venv/bin/python -m serve.server --engine strata --config '+shlex.quote(str(R/'configs/production-Q4.json'))+' --host 127.0.0.1 --port 8080'
    icommand=qcommand.replace('production-Q4.json','production-IQ3_S.json')
    chunks=[line for row in diagnostics['runs'] for line in row['prefill_timing_lines']]
    phase_lines=[line for row in final for line in row.get('normal_stage_timing_lines',[]) if line.startswith('strata decode timing:')]
    deltaPP={x['target']:x['pp_tps']['delta_percent'] for x in controlled};controlnotes=', '.join(f'{t} actual: {deltaPP[t]:+.2f}%' for t in [31400,63400,127000,259500])
    fixed_cpu=arg(cfg,'--pool-workers');fixed_pcie=arg(cfg,'--pcie-frac');fixed_minp=arg(cfg,'--spec-min-p');fixed_spec=arg(cfg,'--spec');fixed_kv=arg(cfg,'--kv');fixed_chunk=arg(cfg,'--prefill')
    zero_reads=all(row.get('expert_file_reads_decode')==0 for row in final)
    agentnotes='; '.join(f'start{t}: initial TTFT {rows[0]["ttft_s"]:.2f}s, turns1–10 medianTTFT {med(rows[1:],"ttft_s"):.2f}s, medianTG {med(rows[1:],"tg_tps"):.2f} tok/s' for t,rows in agents.items())
    if (R/'evidence/agent128-attempt1-failure.json').exists():
        agentnotes+='. Pierwsza sesja128K zachowana jako PARTIAL: turn8 naturalny stop188tokenów poniżej minimum256, bez OOM/crash/toolcall. Wybrana sesja to osobno oznaczone pełne powtórzenie z tymi samymi zadaniami/sampling i nowymi nonce; nie restartowano procesu w trakcie jej tur'
    longnotes='; '.join(f'actual{r["actual_prompt_tokens"]}+{r["generated_tokens"]}: TG {r["tg_tps"]:.2f}' for r in longs)
    incomplete_long=load(R/'raw/long-decode-done.json').get('incomplete_attempts',[])
    if incomplete_long:
        longnotes+='; zachowane niepełne próby: '+', '.join(f'actual{row["actual_prompt_tokens"]}, {row["generated_tokens"]}/{row["requested_output"]} output, TG {row["tg_tps"]:.2f}, naturalny stop' for row in incomplete_long)+'. Pełny 8K pochodzi z osobno oznaczonego jednego powtórzenia tego samego zadania i sampling z nowym nonce; nie ignorowano EOS'
    compnotes='; '.join(f'actual{r["actual_prompt_tokens"]} → {r["generated_tokens"]} summary tokens: {r["total_wall_s"]:.2f}s total (TTFT {r["ttft_s"]:.2f}s)' for r in compaction)
    answers=[
        ('Co poprawiło v0.1.32?',f'Kontrolowane porównanie całego runtime z identycznymi requestami/K24/INT8/prefillauto pokazuje niewielki wzrost PP: {controlnotes}. Zyski finalnego tuningu są osobnym NOT_CONTROLLED_A_B. Release dodaje równoległy refill oraz opcjonalne nowe ścieżki; sam wynik nie izoluje przyczyny do jednego patcha.'),
        ('Zmiana Q4 PP',f'{controlnotes}. Pełne wyniki i best-config before/after: comparison-upgrade.md/.csv/.json. Przy małych deltach uwzględnij rozrzut runów; nie traktuj ich jako dowodu dużego przyspieszenia.'),
        ('Zmiana Q4 TG','TG ma wyraźny rozrzut i zależy od promptu/adaptive placement oraz MTP. Kontrolowane pary i finalne best-config wartości są oddzielone w tabeli upgrade; zmiany split/KV/prefill/workers/MTP nie są efektem samego upgrade.'),
        ('Czy multi-GPU prompt fix pomaga 2×4090?',f'Przy K24/full arena/INT8/prefillauto widać powyższe niewielkie dodatnie mediany PP; przy259500 actual delta wynosi {deltaPP[259500]:+.2f}%. Nie wykonano prywatnego cofnięcia wyłącznie tego patcha, więc jest to whole-version A/B. Duży wzrost PP przy większym chunku stanowi osobny tuning.'),
        ('Czy Q4-fast build jest wart używania?','Nie został dopuszczony do modelowych pomiarów: STRATA_MMQ_KQUANTS=ON skompilował się, ale upstreamowy test numeryczny Q4_K gate/up-1 zgłosił unwritten/non-finite output. Zachowano logi, nie patchowano engine. Nie ma uczciwego wyniku speedA/B ani podstaw do production recommendation tego builda; default został użyty.'),
        ('Najlepszy layer split',f'Wśród przetestowanych K20/22/24/26 i auto wygrał {topology["winner"]}; final K={cfg["layer_split"]}. TOP2 potwierdzono trzema runami po warmupie. To lokalne optimum w badanym zakresie, nie dowód globalnego optimum wszystkich48granic.'),
        ('Najlepszy prefill',f'Wybrano jawne {prefill["argument"]}; argument32768 upstream zmniejszał do16384. Obie potwierdzone polityki dawały bardzo podobne PP; jawny16384 nie polega na automatycznej redukcji. Final argument={fixed_chunk}, actualchunk/borrowedslots zapisane w startupach oraz allocation evidence.'),
        ('Czy STRATA_SPLIT_OWN ma sens?','Screening64/128K nie osiągnął >5% przewagi względem default. Tryb silnie zmniejsza dostępny expert cache przez osobne bufory; jest NON_BIT_IDENTICAL_OPT_IN i pozostaje osobno. --no-prefill-borrow również przegrało screening. Domyślna ścieżka zachowana do tuningu.'),
        ('Najlepszy KV przy128/256K',f'Final KV={fixed_kv}, klasyfikacja {selection["classification"]}. Wszystkie legalne INT8/K8V4/Q4_0/rotatedINT8 miały screening n2 na obu kontekstach, TOP2 n3. Wybór według geometrycznej średniej potwierdzonych TG; alternatywne wyjścia oraz textdiff zapisane osobno, bez założenia jakościowej równoważności. K8V4 nie łączono z kv-resident.'),
        ('Najlepsze MTP',f'Final spec={fixed_spec}, min-p={fixed_minp}; spec2/3/4/5 miały po2 requesty z actual1024output, TOP2 po3. MTP OFF jest UNSUPPORTED_BY_CURRENT_UPSTREAM dla tego nativepack/serve; nie podaję wymyślonego raw-non-MTP ani speedupu względem OFF. Normal counters obejmują MTP i suffix lookup.'),
        ('Workers / PCIe / min-p',f'Final pool-workers={fixed_cpu}, pcie-frac={fixed_pcie}, spec-min-p={fixed_minp}. Upstream calibrator: {calibration["upstream"]["settings"]}; default {calibration["upstream"]["report"]["default"]}. Lokalne64K screens były sekwencyjne, bez Cartesianproduct; zwycięski zestaw potwierdzony warmup+3.'),
        ('PP/TG przy32/64/128/256K','Tabela główna poniżej zawiera mediany dokładnie3runów/actualcontext,256output,greedy,zero reuse,max262144. Prompt API count zgadza się z tokenizerem; occupancy nie pochodzi z configuredcontext.'),
        ('Long-decode TG',longnotes+'. Wszystkie długości output potwierdzone. Sampling temp1/top_p0.95/top_k20. Rolling/cumulativeTG na wykresie oraz normal acceptance z upstream trace; trace overhead jest w timingach.'),
        ('Agentic multi-turn latency',agentnotes+'. Każda sesja to jeden nieprzerwany engine i11requestów, zwykły prefixreuse. Jest to symulacja na prawdziwych fragmentach repozytorium, nie działająca integracja OpenCode ani wykonanie proponowanych przez model patchy.'),
        ('Compaction128K/250K',compnotes+'. Transcript z rzeczywistych zapisanych sesji i odpowiedzi; krótka historia/decyzje zostają kompletne, rozmiar ogranicza jedynie starsze duże fragmenty repo. Oldruntime control używa identycznego payloadu w nowym namespace, oba konfiguracje podano jako NOT_CONTROLLED_A_B.'),
        ('Czy decode ma expert SSD reads?',f'Normal logical expert file fetches w finalnej macierzy: {"zero we wszystkich12runach" if zero_reads else "zobacz poszczególne wyniki summary; nie wszystkie są zero"}. Full native RAM arena przechowuje cały routed set; CPU misses korzystają z RAM. Odczyty PLE/embedding i fizyczny hostSSD za virtiofs są osobne. Zero file_blobs nie dowodzi zera wszystkich fizycznych SSD reads całego procesu.'),
        ('Bottleneck','Ocena opiera się na normal decode-stage timings, osobnej diagnostyce prompt kernels oraz GPU/CPU/PCIe telemetry. GPU-reach wait zawiera oczekiwanie na pracę/transfery, nie stanowi samego czasu kernela; nie wolno sumować zachodzących timeline obu GPU jako wall time. Dokładne linie diagnostyczne znajdują się poniżej. Storage ekspertów nie jest per-token źródłem przy fullarena/zerofilefetch; pozostałe odczyty fizycznego hosta nie są przypisane. Końcowy wniosek bottleneck wymaga sprawdzenia tych dominujących kosztów i wykresów.'),
        ('Q4 jako praktyczny model OpenCode vsIQ3_S','Zmierzono koszty read/reuse/longdecode/compaction Q4 i dwa kontrolne konteksty IQ3. Są to dane do wyboru modelu pod latency i RAM; wyższy bitrate nie dowodzi lepszej jakości. Odpowiedzi trzech identycznych qualitypromptów zapisano do ręcznego porównania. Nie orzekam, że Q4 jest jakościowo lepszy. Finalna decyzja praktyczna musi uwzględnić tabelę IQ3/runtimeupgrade i zmierzone latency agentic.'),
        ('Finalny configQ4',f'configs/production-Q4.json, defaultbuildv0.1.32, fullRAMarena, obie4090, K={cfg["layer_split"]}, prefill={fixed_chunk}, KV={fixed_kv}, spec={fixed_spec}, workers={fixed_cpu}, pcie={fixed_pcie}, min-p={fixed_minp}. Wszystkie envoptins i pełne args w configu. Wyboru produkcyjnego nie nazywam jakościowo równoważnym do innych KV bez ręcznego przeczytania savedquality.'),
        ('Finalny configIQ3_S','configs/production-IQ3_S.json zachowuje poprzedni najlepszy config i istniejące modele/MTP; zmienia runtime do osobnego v0.1.32. Wykonano tylko64K×3 i256K×3. Jeśli autoK zmienił się, tabela oznacza NOT_CONTROLLED_A_B; nie robiono nowego pełnego tuningu IQ3.')]
    lines=['# Q4 Strata v0.1.32 — raport do końcowego przeglądu','','Status: pomiary zakończone; niezależny przegląd tabel, wykresów i completion-audit wymagany przed uznaniem całej kampanii za COMPLETE.','','HEAD `c499bd102e7a4135c0de389dcfe38c399759ccc8`, tagv0.1.32, defaultbuild; Unsloth revision `38bb39ee97821de2c9009abb7e93950eec396e66`. Stara kampania v0.1.31 zachowana podq4-max-sweep; stare runy z PSS1Hz są EXCLUDED_TELEMETRY_PSS, nie użyte do selekcji. Hardware/driver/CUDA/kernel/PCIe: environment.json. Release/source/help audit: release-delta.md. Hostsource/KVgeometry/counter scopes: architecture-notes.md.','','Każdy rawresult przechowuje runtime/modelidentity, topology i pełny config/command. PSS tylko poza clockiem requestu; około1Hz RSS/CPU/RAM/GPU/power/PCIe/I/O. RAM_used=MemTotal−MemAvailable, RSS/PSS osobno. Null oznacza niedostępny counter. Warmup/smoke/diagnostyka nie są mierzoną komórką finalnej macierzy.','']
    for i,(question,answer) in enumerate(answers,1):lines.extend([f'{i}. **{question}** {answer}',''])
    lines.extend(['## Finalna macierz actualcontext','','RAM/VRAM to mediana requestowych peaków, MTP accept to mediana normal accepted/offered. Trzy runy/wiersz.','',table(['Actual prompt','PP tok/s','TG tok/s','TTFT s','RAM GiB','VRAM0 GiB','VRAM1 GiB','MTP accept %'],context),'','## Porównanie upgrade','',table(['Metric','v0.1.31','v0.1.32','Delta %','Classification'],[[x['metric'],x['v0131'],x['v0132'],x['delta_percent'],x['classification']] for x in comparison['rows']]),'','Pełne konfiguracje, raw paths i ograniczenia kontroli w comparison-upgrade.json/.csv.',''])
    for target,rows in agents.items():
        lines.extend([f'## Agentic start{target}','',table(['Turn','Total ctx','Reused','New PP tokens','TTFT s','PP tok/s','TG tok/s','Wall s'],[[row['turn'],row['actual_prompt_tokens'],row['cache_reused_tokens'],row.get('timings',{}).get('prompt_n'),row['ttft_s'],row['pp_tps'],row['tg_tps'],row['total_wall_s']] for row in rows]),''])
    lines.extend(['## Quality / parity / needle','','BezLLMjudge, bez rankingu jakości. Fullresponses+SHA256+textdiff w quality/<variant>/; źródłowe exactAPIpayloads w quality/requests/ i source-manifest.json.','',table(['Variant','Status','Text identical to reference','Output tokens'],[[v['variant'],v['status'],sum(x['text_identical'] for x in v.get('rows',[])),' / '.join(str(x['generated_tokens']) for x in v.get('rows',[]))] for v in quality['variants']]),'','Upstreamneedle: seed7, te same words/depths/question/greedy40, tokenizer-sizing zamiast characterestimate. Found jest mechanicznym kryterium upstreamu.','',table(['Actualctx','Depth %','Found','Answer'],[[x['actual_prompt_tokens'],x['depth'],x['found'],x['answer'].replace('\n',' ').replace('|','/')] for x in needle['results']]),'','## Normal timing evidence','','Request-local decode summaries; per-stage lines mogą być cumulative i nie są tu przedstawiane jako perrequestcost.','```text',*phase_lines,'```','','Osobne diagnostyczne128/256K prefille (nieperformancewinners):','```text',*chunks,'```','','## Commands','','Uruchamiaj modele pojedynczo. Configi zachowują przypięte localmodels i spec/KV/env; pokazane polecenia nie zostały automatycznie uruchomione jako serwer produkcyjny.','```bash',qcommand,'```','','```bash',icommand,'```','','## Limitations and review','','Wykresy: plots/ (PNG/SVG i source-manifest). Summary.csv/json przechowują szczegółowe requesty; counters per-GPU expert share i fizyczneSSD są null gdy upstream/VM ich nie udostępnia. Nie użyto drop_caches. Coldstart=exec→healthREADY świeżego procesu, nie dowód fizycznie zimnego filesystemcache. Nie patchowano upstream ani wag, nie pobierano modeli ponownie, nie commitowano/pushowano.','','Ten raport wymaga sprawdzenia wniosków17/18 względem rzeczywistych timings/plots i dopisania konkretnej interpretacji bottleneck/używalności. Completion-audit ma potwierdzić zakres, a nie samą obecność plików.'])
    if (R/'final-matrix-attempt.json').exists():
        lines += ['', '## Final matrix prompt policy and retained failure', '', 'Original FINAL-v0132-Q4 attempt stopped after read_file tool-call EOS at118 outputtokens in the first32K measured request. All original raw/log/telemetry files are preserved and excluded from the256-output final matrix. FINAL-v0132-Q4-attempt2 adds an explicit offline/no-tools instruction to the SYSTEM message; corpus, usertask, greedy sampling, requested lengths, unique nonces and tokenizer sizing are unchanged. No engine patch, tool-choice workaround or EOS suppression was used. Best-config old/new comparisons are NOT_CONTROLLED_A_B, including this prompt-policy difference. Exact old/new policies and config/script revisions: final-matrix-attempt.json and recovery/final-attempt1/. Quality requests and paired version controls remain literal originals.']
    (R/'report.md').write_text('\n'.join(lines)+'\n');(R/'raw/report-assembly.json').write_text(json.dumps({'status':'ASSEMBLED_REQUIRES_INDEPENDENT_REVIEW','created':time.time(),'answers':20,'configQ4':str(R/'configs/production-Q4.json'),'configIQ3':str(R/'configs/production-IQ3_S.json'),'manual_review_required':['Allnumericclaims againstraw','Specificbottleneckinterpretation(question17)','PracticalOpenCodecomparison(question18)','Renderedplots','Source/model/oldartifactintegrity','Completeusersections0–26audit']},indent=2));print('Report assembled; final independent interpretation/audit remains.')
